with cleaned as (select id, full_name, email, dept_id, manager_id, hire_date, is_remote, level, concat_ws(',', full_name, job_title) as full_name_job_title_key, coalesce(level, 'NONE') as level_filled from employees where hire_date >= to_date('2023-07-18') and full_name like 'I%') select * from (select *, rank() over (partition by dept_id order by hire_date desc) as row_num from cleaned) x where row_num = 1;
